#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/code-format.py.tmpl. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check or format files"
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--all" help="format every file of this repository, not only the uncommitted files"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="apply fixes"
# USAGE arg "[files]" var=#true help="the files to format; the default is the uncommitted files"

import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The flag line of --all in a gate file: "#USAGE" or "# USAGE".
ALL_FLAG = re.compile(rb'^# ?USAGE flag "--all"', re.MULTILINE)


def declares_all(path):
  """Whether the gate file path declares the flag --all."""
  try:
    with open(path, "rb") as f:
      return ALL_FLAG.search(f.read()) is not None
  except OSError:
    return False


# An empty list adds no argument.
debug = ["--debug"] if os.environ.get("usage_debug") == "true" else []
fix = ["--fix"] if os.environ.get("usage_fix") == "true" else []

# The pre-commit hook passes the staged files. Without files and without
# --all, each gate examines the uncommitted files of this repository.
files = helpers.usage_files()
all_flag = []
if os.environ.get("usage_all") == "true":
  if files:
    helpers.print_error("Use --all or files, not both.")
    sys.exit(2)
  all_flag = ["--all"]

# The formatters: each code:format:<name> task, from a tool or from this
# repository, in the order of its number (05-dprint first). Each gets the
# same flags and files, and gets its own list from gate_files of helpers.
# --all goes only to a gate that declares it: an older gate of a repository
# without it gets --fix, --debug and the files. The gate file is the file
# that mise runs for the name: <path> when it exists, else <path>.py. The
# flag line is "#USAGE" or "# USAGE". The first gate that fails stops the
# task with its code.
for task in helpers.own_tasks("code:format"):
  gate_all = []
  part = f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/{task.replace(':', '/')}"
  if not os.path.isfile(part):
    part = f"{part}.py"
  if all_flag and declares_all(part):
    gate_all = all_flag
  rc = subprocess.run(["mise", "run", task, *gate_all, *fix, *debug, *files], check=False).returncode
  if rc != 0:
    sys.exit(rc)
helpers.print_success("Formatting done")
